const PAIE_ETATS = [["journal", "Journal des salaires (livre de paie)", "Toutes les rubriques par salarié pour la période."], ["recap", "Récapitulatif des cotisations", "Cotisations salariales et patronales par organisme et par rubrique."], ["charges", "Tableau des charges", "Brut, charges et coût employeur par salarié."], ["regl", "État des règlements", "Net à payer et coordonnées bancaires, avec fichier de virement SEPA."], ["registre", "Registre unique du personnel", "Entrées et sorties, emplois, contrats (obligatoire)."], ["releve", "Relevé individuel annuel", "Cumuls de l'année par salarié."], ["cp", "Provision pour congés payés", "Solde de congés valorisé, charges comprises."], ["od", "État des OD de paie", "Écriture comptable de la période."], ["allg", "Allègements de cotisations", "Réduction générale et heures supplémentaires."]];
