  if (k === "charges") { out.head = ["Salarié", "Brut", "Charges patronales", "Taux", "Allègements", "Coût employeur"]; L.forEach(B => { const al = -B.R.filter(r => r.mP < 0).reduce((a, r) => a + r.mP, 0); out.rows.push([pNom(B.s), eur(B.brut), eur(B.cotP), B.brut ? Math.round(B.cotP / B.brut * 100) + " %" : "", eur(al), eur(B.cout)]); }); out.rows.push({ cells: ["Total", eur(T("brut")), eur(T("cotP")), T("brut") ? Math.round(T("cotP") / T("brut") * 100) + " %" : "", "", eur(T("cout"))], style: "tot" }); }
